def _permissoes_novas() -> None:
    """Perfis padrão já criados nos escritórios ganham as permissões de Tribunais (o que o escritório tirou continua fora)."""
    import json

    conn = op.get_bind()
    for pid, nome, perms in conn.execute(sa.text("SELECT id, nome, permissoes FROM perfil_acesso WHERE administrador = :f"),
                                         {"f": False}).all():
        if nome not in NOVAS:
            continue
        atuais = perms if isinstance(perms, list) else json.loads(perms or "[]")
        novas = sorted(set(atuais) | set(NOVAS[nome]))
        if novas != sorted(atuais):
            conn.execute(sa.text("UPDATE perfil_acesso SET permissoes = :p WHERE id = :i").bindparams(sa.bindparam("p", type_=sa.JSON)),
                         {"p": novas, "i": pid})


